0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":3754,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 13.25\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T87b,"])self.__next_f.push([1,"The Lord informs Arjuna that the conditioned souls can be divided into two classes as far as man’s search for self-realization is concerned. Those who are atheists, agnostics and skeptics are beyond the sense of spiritual understanding. But there are others, who are faithful in their understanding of spiritual life, and they are called introspective devotees, philosophers, and workers who have renounced fruitive results. Those who always try to establish the doctrine of monism are also counted among the atheists and agnostics. In other words, only the devotees of the Supreme Personality of Godhead are best situated in spiritual understanding, because they understand that beyond this material nature are the spiritual world and the Supreme Personality of Godhead, who is expanded as the Paramātmā, the Supersoul in everyone, the all-pervading Godhead. Of course there are those who try to understand the Supreme Absolute Truth by cultivation of knowledge, and they can be counted in the class of the faithful. The Sāṅkhya philosophers analyze this material world into twenty-four elements, and they place the individual soul as the twenty-fifth item. When they are able to understand the nature of the individual soul to be transcendental to the material elements, they are able to understand also that above the individual soul there is the Supreme Personality of Godhead. He is the twenty-sixth element. Thus gradually they also come to the standard of devotional service in Kṛṣṇa consciousness. Those who work without fruitive results are also perfect in their attitude. They are given a chance to advance to the platform of devotional service in Kṛṣṇa consciousness. Here it is stated that there are some people who are pure in consciousness and who try to find out the Supersoul by meditation, and when they discover the Supersoul within themselves, they become transcendentally situated. Similarly, there are others who also try to understand the Supreme Soul by cultivation of knowledge, and there are others who cultivate the haṭha-yoga system and who try to satisfy the Supreme Personality of Godhead by childish activities."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":3754,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"25\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 25\",\"advanced_view_url_path\":\"/en/library/bg/13/advanced-view/#bb3308\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"}